  function makeMatchTiles(qs,r){const ids=new Map(),tiles=[];let next=0;qs.forEach((q,i)=>{const k=matchAnswerKey(q.opts[q.correct]);if(!ids.has(k))ids.set(k,++next);const pair=ids.get(k);tiles.push({pair,kind:'q',html:q.text,icon:'?'},{pair,kind:'a',html:q.opts[q.correct],icon:'='})});return shuffle(tiles,r).map((x,i)=>({...x,id:i,removed:false}))}
  function buildMatch(topic,seed,count=12){if(typeof topic.matchPairs!=='function')return build(topic.id,seed,count);const r=rng(seed),pairs=topic.matchPairs(r,count);if(!Array.isArray(pairs)||pairs.length!==count)throw Error(`Chủ đề ${topic.id} phải tạo đúng ${count} cặp Pikachu`);const seen=new Set(),results=new Set();return pairs.map((p,i)=>{const answer=p.answer||'',key=matchAnswerKey(answer),result=matchAnswerKey(p.result);if(!p.text||!answer||!result)throw Error(`Cặp Pikachu ${i+1} của ${topic.id} thiếu câu hỏi, đáp án hoặc kết quả`);if(seen.has(key)||results.has(result))throw Error(`Cặp Pikachu ${i+1} của ${topic.id} có đáp số trùng`);seen.add(key);results.add(result);return {text:p.text,answer,explain:p.explain||'',opts:[answer],correct:0,matchResult:p.result,matchKind:p.kind}})}
