  function pickMatch(i){const v=view;if(!v||v.mode!=='match'||v.lock||v.tiles[i].removed)return;tone('select');const b=document.querySelector(`[data-match-pos="${i}"]`);if(v.selected==null){v.selected=i;b.classList.add('selected');const t=v.tiles[i];matchStatus('','preview',`<b>Đã chọn ${t.kind==='q'?'câu hỏi':'đáp án'}:</b> <span>${t.html}</span>`);return}if(v.selected===i){b.classList.remove('selected');v.selected=null;matchStatus('Đã bỏ chọn ô.');return}const a=v.selected,A=v.tiles[a],B=v.tiles[i],path=matchPath(a,i);v.lock=true;if(path){showMatchPath(path);tone('right');document.querySelector(`[data-match-pos="${a}"]`).classList.add('matched');b.classList.add('matched');v.score+=100+Math.ceil(v.left/6);v.matched++;matchStatus('🔔 Chính xác! Đường nối hợp lệ.','right');setTimeout(()=>{A.removed=true;B.removed=true;v.selected=null;v.lock=false;document.querySelector(`[data-match-pos="${a}"]`)?.classList.add('removed');b.classList.add('removed');document.querySelector('#matchScore').textContent=v.score;document.querySelector('#matchCount').textContent=v.matched+'/12';if(v.matched>=12)return matchResult(true);if(!matchMove()){matchStatus('Không còn đường nối. Bảng được tự động xáo miễn phí.','note');setTimeout(()=>shuffleMatch(true),450)}},390)}else{tone('wrong');const first=document.querySelector(`[data-match-pos="${a}"]`);first.classList.add('wrong');b.classList.add('wrong');v.score=Math.max(0,v.score-20);v.mistakes++;const lives=document.querySelector('#matchLives'),left=v.maxMistakes-v.mistakes;if(lives)lives.textContent='❤️'.repeat(left)+'🖤'.repeat(v.mistakes);matchStatus(left?`❌ Chưa đúng. Em còn ${left} lần chọn sai.`:'💥 Sai 3 lần! Game Over.','wrong');setTimeout(()=>{first.classList.remove('wrong','selected');b.classList.remove('wrong');v.selected=null;document.querySelector('#matchScore').textContent=v.score;if(!left)return matchResult(false,true);v.lock=false},520)}}
