    el.className='game-arena adventure-bg adv-result-bg';el.innerHTML=`<section class="adv-result"><div class="game-cup">${lost?'💔':v.wrong.length?'🏁':'🏆'}</div><h1>${lost?'Hết tim – vào phòng luyện!':v.wrong.length?'Hoàn thành hành trình!':'Chinh phục hoàn hảo!'}</h1>${lost?`<p class="adv-perfect">Em dừng ở cổng ${done}/${total}. Xem lại các câu sai rồi thử lại nhé.</p>`:''}<div class="adv-result-numbers"><span><b>${correct}/${done}</b><small>Câu đúng</small></span><span><b>🔥 ${v.stars}</b><small>Điểm combo</small></span><span><b>${done?Math.round(100*correct/done):0}%</b><small>Độ chính xác</small></span></div>${starsLine(aw)}${review?`<section class="adv-review"><h2>📚 Phòng luyện lại câu sai</h2>${review}</section>`:'<p class="adv-perfect">Không có câu sai. Cú Tri Thức đã mở toàn bộ kho báu!</p>'}<div class="row"><button class="btn ${lost?'':'primary'}" id="advAgain">Chơi lại màn này</button>${v.wrong.length?`<button class="btn ${lost?'primary':''}" id="advRetry">Luyện lại câu sai</button>`:''}<button class="btn" id="advExit">Chọn chủ đề</button></div></section>`;
