  function studentClassBody(q,r,mine){return `<section class="ga-options">${q.opts.map((o,k)=>`<button data-o="${k}" ${mine||r.reveal?'disabled':''} class="${r.reveal&&k===q.correct?'right':''} ${mine&&mine.choice===k?'picked':''}"><b>${LET[k]}</b><span>${o}</span></button>`).join('')}</section>${mine&&!r.reveal?'<div class="game-wait">Đã gửi đáp án · Chờ giáo viên…</div>':''}`}
