  async function revealClass(r,q,answers){if(!view||!view.host||r.reveal||view.revealing)return;view.revealing=true;const updates={'meta/reveal':true,'meta/revealDeadline':Date.now()+(r.revealSeconds||7)*1000};if(r.gameMode==='race'){Object.entries(r.players||{}).forEach(([uid,p])=>{const a=answers[uid],ok=!!a&&a.choice===q.correct,remain=Math.max(0,(r.deadline-((a&&a.at)||r.deadline))/1000),combo=ok?(p.combo||0)+1:0,energy=ok?(p.energy||0)+1:0,nitro=energy>=3,boost=ok?7+Math.round(4*remain/r.limit)+(nitro?7:0):(a?2:0);updates[`players/${uid}/score`]=(p.score||0)+(ok?score(remain,r.limit):0);updates[`players/${uid}/correct`]=(p.correct||0)+(ok?1:0);updates[`players/${uid}/combo`]=combo;updates[`players/${uid}/energy`]=nitro?0:energy;updates[`players/${uid}/nitro`]=(p.nitro||0)+(nitro?1:0);updates[`players/${uid}/distance`]=Math.min(100,(p.distance||8)+boost)})}else Object.entries(answers).forEach(([uid,a])=>{const p=(r.players||{})[uid];if(!p)return;const ok=a.choice===q.correct,remain=Math.max(0,(r.deadline-(a.at||r.deadline))/1000);updates[`players/${uid}/score`]=(p.score||0)+(ok?score(remain,r.limit):0);updates[`players/${uid}/correct`]=(p.correct||0)+(ok?1:0)});try{await roomRef.update(updates)}catch(e){view.revealing=false;console.error(e)}}
