  function wrongSummaryHTML(r,players){const qs=view.qs||[],stats=qs.slice(0,r.count||qs.length).map((q,index)=>{const rows=Object.values((r.answers&&r.answers[index])||{}),counts=[0,0,0,0];rows.forEach(a=>{if(Number.isInteger(a.choice)&&a.choice>=0&&a.choice<4)counts[a.choice]++});const wrong=rows.filter(a=>a.choice!==q.correct).length;return {q,index,counts,answered:rows.length,wrong}}).filter(x=>x.wrong>0).sort((a,b)=>b.wrong-a.wrong||b.answered-a.answered||a.index-b.index).slice(0,5);if(!stats.length)return '<section class="class-review review-perfect"><h2>🎉 Cả lớp không có câu trả lời sai</h2><p>Thầy có thể tuyên dương cả lớp ngay trên màn hình tổng kết.</p></section>';return `<section class="class-review"><h2>🧠 ${stats.length} câu cần chữa</h2><p class="review-lead">Xếp theo số học sinh trả lời sai, từ nhiều đến ít.</p>${stats.map((x,rank)=>`<article class="review-card"><header><b>${rank+1}. Câu ${x.index+1}</b><span>${x.wrong}/${x.answered} em trả lời sai · ${x.answered?Math.round(100*x.wrong/x.answered):0}%</span></header><div class="review-question">${x.q.text}</div><div class="review-options">${x.q.opts.map((o,k)=>`<div class="${k===x.q.correct?'correct':''}"><b>${LET[k]}</b><span>${o}</span><em>${x.counts[k]} lượt chọn</em></div>`).join('')}</div><div class="review-solution"><b>Đáp án ${LET[x.q.correct]}.</b> ${x.q.explain}</div></article>`).join('')}</section>`}
