  function fitHostProjection(){const arenaEl=document.querySelector('.game-arena.host-view'),main=arenaEl&&arenaEl.querySelector('.class-play-main');if(!arenaEl||!main||hostFitting||!main.clientWidth||!main.clientHeight)return;hostFitting=true;try{let lo=16,hi=Math.min(64,main.clientWidth/14);const fits=size=>{arenaEl.style.setProperty('--host-fs',size+'px');const question=main.querySelector('.ga-question'),cards=[...main.querySelectorAll('.host-options>div')],texts=[...main.querySelectorAll('.host-options>div>span')];return main.scrollHeight<=main.clientHeight+2&&(!question||question.scrollHeight<=question.clientHeight+2&&question.scrollWidth<=question.clientWidth+2)&&cards.every(x=>x.scrollHeight<=x.clientHeight+2&&x.scrollWidth<=x.clientWidth+2)&&texts.every(x=>x.scrollWidth<=x.clientWidth+2)};if(!fits(hi)){for(let n=0;n<14;n++){const mid=(lo+hi)/2;if(fits(mid))lo=mid;else hi=mid}arenaEl.style.setProperty('--host-fs',Math.floor(lo)+'px')}}finally{requestAnimationFrame(()=>hostFitting=false)}}
